python3 << 'EOF'
import re

# Read the file
with open('/app/resources/treasury_bulletin_1970_12.txt') as f:
    content = f.read()

# Find the section with 9-month and one-year bills
start_idx = content.find('9-month and one-year:')
end_idx = content.find('Footnotes at end of Table', start_idx)

section = content[start_idx:end_idx]

# Parse each line
lines = section.split('\n')

# Dictionary to store data by issue month
# Key: (year, month), Value: {'9-month': amount, '12-month': amount}
data_by_month = {}

for line in lines:
    if '|' not in line:
        continue
    parts = [p.strip() for p in line.split('|') if p.strip()]
    if not parts or parts[0].startswith('9-month'):
        continue

    # Parse issue date
    issue_raw = parts[0]

    # Determine the year-month
    if issue_raw == 'Dec. 31':
        year, month = 1969, 12
    elif issue_raw == '1970-Jan. 31':
        year, month = 1970, 1
    elif issue_raw in ['Feb. 2', 'Feb. 28']:
        year, month = 1970, 2
    elif issue_raw == 'Mar. 2':
        year, month = 1970, 3
    elif issue_raw == 'Mar. 31':
        year, month = 1970, 3
    elif issue_raw == 'Apr. 30':
        year, month = 1970, 4
    elif issue_raw == 'May 31':
        year, month = 1970, 5
    elif issue_raw == 'June 1':
        year, month = 1970, 6
    elif issue_raw == 'June 30':
        year, month = 1970, 6
    elif issue_raw == 'July 31':
        year, month = 1970, 7
    elif issue_raw == 'Aug. 31':
        year, month = 1970, 8
    elif issue_raw == 'Sept. 30':
        year, month = 1970, 9
    elif issue_raw == 'Oct. 31':
        year, month = 1970, 10
    elif issue_raw == 'Nov. 2':
        year, month = 1970, 11
    elif issue_raw == 'Nov. 30':
        year, month = 1970, 11
    else:
        continue

    # Parse days to maturity and amount maturing
    days_list = parts[2].split()
    amount_maturing_list = parts[8].split() if len(parts) > 8 else []

    # Initialize month entry
    key = (year, month)
    if key not in data_by_month:
        data_by_month[key] = {'9-month': 0, '12-month': 0}

    # Process each bill type
    for i, days in enumerate(days_list):
        if i >= len(amount_maturing_list):
            break
        amount = amount_maturing_list[i]
        # Clean amount (remove commas, 'r' marks)
        amount = amount.replace(',', '').replace('r', '')
        try:
            amount_val = float(amount)
        except:
            continue

        # Classify by days to maturity
        days_clean = days.replace('d', '')
        try:
            days_val = int(days_clean)
        except:
            continue

        if days_val in [271, 272, 273, 274, 275, 276]:  # ~9 months
            data_by_month[key]['9-month'] += amount_val
        elif days_val == 365:  # 12 months
            data_by_month[key]['12-month'] += amount_val

# Print data for Nov 1969 to Feb 1970
print("Data by month (Nov 1969 - Feb 1970):")
print("="*60)

# Need to also handle Nov 1969 - the Dec 31 row has reference to Nov 30 original issue
# Based on the table header showing "1969-Nov. 30", this was a reopening
# For our purposes, we need to include both Nov and Dec 1969 data

# The issue dates we have are Dec 1969, Jan 1970, Feb 1970
# But for "calendar months November 1969 to February 1970"

# Let's print all available data
for year in [1969, 1970]:
    for month in range(1, 13):
        key = (year, month)
        if key in data_by_month:
            d = data_by_month[key]
            month_name = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][month-1]
            print(f"{year}-{month_name:3}: 9-month: {d['9-month']:8.1f}, 12-month: {d['12-month']:8.1f}, Total: {d['9-month']+d['12-month']:8.1f}")
EOF
